import { MainWrapper } from "./index.stitches";

function Topper() {
  return (
    <header>
      <MainWrapper>
        Hi, I'm Agnes! I am currently a D.C.-based Designer at The
        Washington Post, where I design and develop interactive stories.
      </MainWrapper>
    </header>
  );
}

export default Topper;
